-- ARL-RKA-1.2 semantic corrections for ARL-KB-014 through ARL-KB-020.
-- Created after human semantic review on 2026-10-03.
-- Previously applied migrations remain immutable.
-- Applicability and framework mappings are intentionally unchanged.

UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Long-lived API keys, tokens, cookies or private keys remain active without known owner, scope or rotation plan.","customer_symptom":"Operators cannot reliably identify which API keys, tokens, cookies, private keys or service credentials remain active, who owns them, what they can access, or when they expire.","credible_failure_or_attack":"Unowned, forgotten, over-scoped or long-lived credentials can remain usable after their original purpose ends and may be reused following leakage, personnel change, system drift or compromise.","affected_assets":["API keys, tokens, cookies and private keys","service and workload identities","tool and downstream-system privileges","secret stores and deployment configuration","credential ownership, scope, expiry and rotation records"],"default_severity":"high","severity_rationale":"Incomplete credential inventory can leave active authority unowned or unmonitored. Final severity depends on credential privilege, reachability, lifetime, exposure and compensating controls.","applicability":["tool-using agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The boundary between the assessed agent and the credentials or workload identities it can use to access tools, providers and downstream systems.","operational_impact":"If long-lived api keys, tokens, cookies or private keys remain active without known owner, scope or rotation plan, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-014 credential, secret-store, workload-identity or service-account change","ARL-KB-014 credential scope, owner, expiry, rotation or revocation-policy change","ARL-KB-014 credential leak, orphaned secret, unexpected use or identity incident","ARL-KB-014 evidence expiry or material scope, environment or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='37d4568c5b8066eb244d3981ef94793544b0ecf18fbb8c24549054de4481b8aa', updated_at='2026-08-06' WHERE id='ARL-KB-014';
UPDATE risk_knowledge_checks SET objective='Determine whether every credential available to the assessed agent has an attributable owner, purpose, scope, storage location, lifecycle state and rotation or expiry policy.', method='Enumerate secret stores, environment references, CI variables, service accounts and observed runtime credential use without exposing secret values. Reconcile discovered credentials against the approved inventory and identify orphaned, duplicate, unused, over-scoped or non-expiring credentials.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-014 assessed system, exact version, environment and credential scope","Authoritative credential or workload-identity inventory with owner, purpose, scope and lifecycle state","Secret-store, environment, CI/CD and runtime references showing which credentials the assessed version can use","Evidence of expiry, rotation, revocation or short-lived issuance where applicable","Tester identity, timestamp and evidence digest"]', pass_condition='ARL-KB-014 passes when all credentials available to the assessed agent are represented in the approved inventory with attributable ownership, necessary scope and documented lifecycle controls, and no tested active credential is orphaned or unexplained.', fail_condition='ARL-KB-014 fails when an active credential available to the assessed system lacks an accountable owner, purpose, known scope, lifecycle state or required rotation/expiry control, or when runtime use cannot be reconciled to the approved inventory.', limitations='This bounded ARL-KB-014 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='9f55fdb91cf5d4543569eed6a3f920b11804153c3440685a6fbf51eac45bf361', updated_at='2026-08-06' WHERE entry_id='ARL-KB-014';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of credential inventory is incomplete and make the remaining risk visible.', recommended_remediation='Assign ownership and expiry, use short-lived workload identity, reduce scopes, revoke unused credentials and monitor anomalous use.', default_owner='Identity and secrets owner', priority='P0', implementation_principles_json='["ARL-KB-014: Give every credential or workload identity an accountable owner, documented purpose and minimum required scope.","ARL-KB-014: Prefer short-lived workload identity and automatic expiry or rotation over long-lived static secrets.","ARL-KB-014: Reconcile secret stores and runtime use against the authoritative inventory and revoke orphaned or unused credentials."]', monitoring='Monitor creation, use, expiry, rotation and revocation of credentials and workload identities; alert the Identity and secrets owner on orphaned credentials, unexpected use, excessive lifetime or scope drift.', containment='Revoke or disable affected credentials, preserve attributable use records, rotate potentially exposed secrets and restore only the minimum required authority after owner review.', retest_acceptance_json='["ARL-KB-014: Every credential available to the exact remediated version is represented in the approved inventory.","ARL-KB-014: Credential owner, purpose, scope and lifecycle state are attributable and current.","ARL-KB-014: Deprecated, revoked, synthetic orphan or otherwise unapproved credentials cannot be used by the assessed runtime.","ARL-KB-014: Reviewer identity, timestamp, assessed version, evidence digest, known limitations and residual-risk decision are recorded."]', content_digest='1b6c58c4c587bfa515ef7a7d86dcf838950df7b819d2987af097a3d3968daaeb', updated_at='2026-08-06' WHERE entry_id='ARL-KB-014';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='4a1fca59bab96e439d9b2acac5db13da86840e5b8e4dc0e02669b6e65c4cb384', updated_at='2026-08-06' WHERE entry_id='ARL-KB-014';
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-014','high','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants.","customer_symptom":"A user or operator may observe persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["RAG or memory-enabled agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between RAG or memory-enabled agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-015 memory, vector-store, index, namespace, cache, backup or retrieval-source change","ARL-KB-015 retention, deletion, restoration or access-boundary change","ARL-KB-015 cross-environment, cross-tenant, stale-store or unexpected persistence evidence","ARL-KB-015 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='c477e354d0ad83803c0eae3d001cfae1c5c615d64ff90ac777e5ce61275404fb', updated_at='2026-08-06' WHERE id='ARL-KB-015';
UPDATE risk_knowledge_checks SET objective='Determine whether every persistent memory, vector, embedding and retrieval store used by the assessed agent is inventoried with owner, environment, namespace, retention and access boundaries.', method='Inventory persistent memory stores, vector databases, indexes, namespaces, replicas, caches, backups and deletion paths. Map which assessed identities can read or write each store, which environment and tenant or project boundary applies, and whether retention and deletion behaviour are documented.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-015 assessed system, version, environment and scope for Memory and vector stores are untracked","ARL-KB-015 control configuration or source location showing how reduce the likelihood and impact of memory and vector stores are untracked and make the remaining risk visible.","ARL-KB-015 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-015 policy, authorization, tool or audit events proving whether the tested memory and vector stores are untracked path executed","ARL-KB-015 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-015 passes when all persistent context and retrieval stores reachable by the assessed version are represented in the governed inventory with attributable ownership, access boundaries, environment, retention and deletion behaviour.', fail_condition='ARL-KB-015 fails when the assessed agent can read from or write to an undeclared persistent store, namespace, replica or backup, or when ownership, environment, retention or deletion behaviour cannot be established with version-bound evidence.', limitations='This bounded ARL-KB-015 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='e8ee229ab832f93f1d6849666cea783c3365bdc51689869dbf849a8444cb288f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-015';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of memory and vector stores are untracked and make the remaining risk visible.', recommended_remediation='Register stores as governed assets, isolate namespaces, restrict write paths, implement retention/deletion and test restoration without cross-tenant data.', default_owner='Data platform owner', priority='P1', implementation_principles_json='["ARL-KB-015: Register every persistent memory, vector, embedding, cache and retrieval store as a governed asset.","ARL-KB-015: Bind stores and namespaces to explicit environments, tenants or projects with least-privilege read and write access.","ARL-KB-015: Define retention, deletion, backup and restoration behaviour and verify retired stores cannot silently remain in use."]', monitoring='For ARL-KB-015, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-015 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-015: “Memory and vector stores are untracked” is no longer reproducible against the exact remediated version.","ARL-KB-015: Authorised in-scope use completes successfully, remains within the documented asset scope for memory and vector stores are untracked, and produces no unintended side effect.","ARL-KB-015: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-015: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='ac4d1d729b2691af71537e0143af74e51ac50926219668151c2e904612e926f2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-015';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='9076a979c831ee283c3d9e641fae6feb614b70a2ec3adfefa120cc2871190b69', updated_at='2026-08-06' WHERE entry_id='ARL-KB-015';
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-015','high','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The same model name can resolve to different weights or behaviour, invalidating prior tests and approvals.","customer_symptom":"A user or operator may observe the same model name can resolve to different weights or behaviour, invalidating prior tests and approvals; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in the same model name can resolve to different weights or behaviour, invalidating prior tests and approvals, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["model and dependency artefacts","build, registry and deployment provenance","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all model-backed agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between all model-backed agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the same model name can resolve to different weights or behaviour, invalidating prior tests and approvals, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-016 model identifier, revision, digest, provider or artifact change","ARL-KB-016 system-prompt, inference-setting or security-relevant model-configuration change","ARL-KB-016 provenance failure, unexpected model drift or mutable-alias resolution change","ARL-KB-016 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='f17308b95ec1df9dfc20ea4173bfc1c73b46b5c3e9f71715d075226cdc3f637f', updated_at='2026-08-06' WHERE id='ARL-KB-016';
UPDATE risk_knowledge_checks SET objective='Determine whether the exact model and inference configuration assessed by ARL can be identified and whether an unreviewed model or configuration change invalidates prior evidence.', method='Record provider, model identifier, immutable revision or digest where available, local artifact hash where applicable, system-prompt/configuration version and security-relevant inference settings. Resolve the deployed runtime to those identifiers, detect mutable aliases or drift, and verify that a material model or configuration change requires targeted reassessment before prior approval is reused.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-016 assessed system, version, environment and scope for Model versions and digests are not pinned","ARL-KB-016 control configuration or source location showing how reduce the likelihood and impact of model versions and digests are not pinned and make the remaining risk visible.","ARL-KB-016 positive and abuse inputs with expected and observed outputs for model and dependency artefacts and build, registry and deployment provenance","ARL-KB-016 policy, authorization, tool or audit events proving whether the tested model versions and digests are not pinned path executed","ARL-KB-016 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-016 passes when the assessed model and security-relevant configuration are attributable to an exact version or immutable evidence reference and material drift cannot silently inherit prior assessment evidence.', fail_condition='ARL-KB-016 fails when the deployed model or relevant inference configuration can change without an attributable version or digest, or when evidence from a materially different model/configuration remains accepted as current.', limitations='This bounded ARL-KB-016 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='589a1c1dbb5dd3b730d5cd411372cbcb3a5f6b0f41691ac02ed50a166482dff6', updated_at='2026-08-06' WHERE entry_id='ARL-KB-016';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of model versions and digests are not pinned and make the remaining risk visible.', recommended_remediation='Pin immutable versions, record provenance, detect drift and require targeted retesting before accepting a changed model or configuration.', default_owner='ML platform owner', priority='P1', implementation_principles_json='["ARL-KB-016: Prefer immutable model revisions, digests or locally verifiable artifact hashes over mutable aliases.","ARL-KB-016: Bind assessment evidence to the exact model, prompt/configuration version and security-relevant inference settings.","ARL-KB-016: Treat material model or configuration drift as a revalidation trigger before prior readiness or closure decisions are reused."]', monitoring='For ARL-KB-016, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the ML platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-016 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-016: “Model versions and digests are not pinned” is no longer reproducible against the exact remediated version.","ARL-KB-016: Authorised in-scope use completes successfully, remains within the documented asset scope for model versions and digests are not pinned, and produces no unintended side effect.","ARL-KB-016: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-016: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='4af2a20c0cabd673031c7483e0f88da06e75761662fb8abbb39fbcea4d66841b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-016';
