UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Development, test and production share data, credentials, queues or tools, allowing tests or compromised lower environments to affect production.","customer_symptom":"A user or operator may observe development, test and production share data, credentials, queues or tools, allowing tests or compromised lower environments to affect production; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in development, test and production share data, credentials, queues or tools, allowing tests or compromised lower environments to affect production, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Weak environment separation can allow lower-trust development or test identities, data and tools to affect production. Final severity depends on reachable production authority, data sensitivity, exposure and compensating controls.","applicability":["agents with multiple environments"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between agents with multiple environments and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If development, test and production share data, credentials, queues or tools, allowing tests or compromised lower environments to affect production, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-018 environment, account, project, network, database, queue, secret or provider-boundary change","ARL-KB-018 new cross-environment route, shared credential, shared data source or production tool endpoint","ARL-KB-018 environment-boundary bypass, drift or incident evidence","ARL-KB-018 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='e96c3e00269f9e34a86463a2f77a778dbad427f5b180ba7bf87b537cf846adf9', updated_at='2026-08-06' WHERE id='ARL-KB-018';
UPDATE risk_knowledge_checks SET objective='Determine whether development, test and production environments are separated across identities, credentials, data, networks, queues, providers and tool endpoints.', method='Compare accounts, projects, networks, databases, queues, secrets, providers and tool endpoints across environments. Using owner-authorised synthetic or production-equivalent resources, verify that a lower-environment identity or route cannot access prohibited production-equivalent data, credentials, tools or queues.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-018 assessed system, version, environment and scope for Environment separation is weak","ARL-KB-018 control configuration or source location showing how reduce the likelihood and impact of environment separation is weak and make the remaining risk visible.","ARL-KB-018 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-018 policy, authorization, tool or audit events proving whether the tested environment separation is weak path executed","ARL-KB-018 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-018 passes when lower environments remain confined to their documented identities, data, networks and tools and cannot reach prohibited production-equivalent resources through the tested paths.', fail_condition='ARL-KB-018 fails when development or test identities, credentials, data paths, queues, networks or tool routes can access or affect prohibited production resources, or when claimed separation cannot be demonstrated.', limitations='This bounded ARL-KB-018 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='fb09173583542866c5d20f66d41c71fb18e2e4885e748860cb56e88a7d75ce7a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-018';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of environment separation is weak and make the remaining risk visible.', recommended_remediation='Separate identities, data, networks, secrets and approvals; use synthetic data by default and block production tool access from lower environments.', default_owner='Platform owner', priority='P0', implementation_principles_json='["ARL-KB-018: Use distinct identities, credentials, networks, data stores and tool endpoints for lower and production environments.","ARL-KB-018: Deny lower-environment access to production resources by default and use synthetic data wherever possible.","ARL-KB-018: Require explicit governed promotion and revalidation before a lower-environment component receives production authority."]', monitoring='For ARL-KB-018, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-018 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-018: “Environment separation is weak” is no longer reproducible against the exact remediated version.","ARL-KB-018: Authorised in-scope use completes successfully, remains within the documented asset scope for environment separation is weak, and produces no unintended side effect.","ARL-KB-018: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-018: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='15d6df8bf28283fe126b0cb460e8ba1306fdf9eb0420810c7eec272f8864a5b7', updated_at='2026-08-06' WHERE entry_id='ARL-KB-018';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='4a1fca59bab96e439d9b2acac5db13da86840e5b8e4dc0e02669b6e65c4cb384', updated_at='2026-08-06' WHERE entry_id='ARL-KB-018';
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-018','high','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Unauthenticated callers or error paths can reach agent state, tools, evidence or administrative functions.","customer_symptom":"A user or operator may observe unauthenticated callers or error paths can reach agent state, tools, evidence or administrative functions; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in unauthenticated callers or error paths can reach agent state, tools, evidence or administrative functions, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["hosted agents and control planes"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between hosted agents and control planes and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If unauthenticated callers or error paths can reach agent state, tools, evidence or administrative functions, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-019 authentication, session, identity-provider, gateway or sensitive-route change","ARL-KB-019 new administrative, evidence, agent-state or tool-control endpoint","ARL-KB-019 authentication bypass, fail-open behaviour, credential-verification incident or session anomaly","ARL-KB-019 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='a37481c06db1aa4dcdfe6a1139f9e291109d58ede832bc9ec2d0203d0e18138d', updated_at='2026-08-06' WHERE id='ARL-KB-019';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: authentication is missing or can fail open.', method='Enumerate every sensitive route and administrative or agent-control function. Call representative routes without credentials, with invalid or malformed credentials, with expired or revoked credentials where safely testable, and during simulated identity-provider or verification failure. Verify authentication is enforced server-side and fails closed before protected state, tools, evidence or functions are exposed.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-019 assessed system, version, environment and scope for Authentication is missing or can fail open","ARL-KB-019 control configuration or source location showing how reduce the likelihood and impact of authentication is missing or can fail open and make the remaining risk visible.","ARL-KB-019 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-019 policy, authorization, tool or audit events proving whether the tested authentication is missing or can fail open path executed","ARL-KB-019 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-019 passes only when “Authentication is missing or can fail open” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-019 fails when unauthenticated callers or error paths can reach agent state, tools, evidence or administrative functions, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-019 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='39f5e2e797eca13416d2896d40b2a1abcf2c0734bb0f5b19be7918fc0f3bea7c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-019';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of authentication is missing or can fail open and make the remaining risk visible.', recommended_remediation='Require server-side authentication on every sensitive path, centralise enforcement and fail closed when identity cannot be verified.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-019: Enforce authentication server-side on every sensitive route rather than relying on model or client behaviour.","ARL-KB-019: Centralise identity verification and fail closed when credentials cannot be validated.","ARL-KB-019: Treat authentication-provider, session and verification failures as denial conditions unless an explicitly approved degraded mode exists."]', monitoring='For ARL-KB-019, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-019 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-019: “Authentication is missing or can fail open” is no longer reproducible against the exact remediated version.","ARL-KB-019: Authorised in-scope use completes successfully, remains within the documented asset scope for authentication is missing or can fail open, and produces no unintended side effect.","ARL-KB-019: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-019: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='ef9ed90671feef51d7a7f3793aec2d3bb65105bc16f6b1c46d3a0d9c7838b9f9', updated_at='2026-08-06' WHERE entry_id='ARL-KB-019';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='d58769d9bd36c814f01cccaf96179ab3ba7cdc706ba3ebf68e4f3dc26390f215', updated_at='2026-08-06' WHERE entry_id='ARL-KB-019';
