UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A stolen password can grant control over prompts, tools, policies, approvals or evidence.","customer_symptom":"A user or operator may observe a stolen password can grant control over prompts, tools, policies, approvals or evidence; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in a stolen password can grant control over prompts, tools, policies, approvals or evidence, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"high","severity_rationale":"Weak privileged authentication can allow takeover of high-impact administrative capabilities. Final severity depends on the authority of affected accounts, exposed functions, recovery controls and compensating safeguards.","applicability":["hosted platforms"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between hosted platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a stolen password can grant control over prompts, tools, policies, approvals or evidence, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-020 privileged authentication, MFA, recovery, factor-enrolment or session-policy change","ARL-KB-020 new privileged role, administrative capability or high-impact operation","ARL-KB-020 phishing, account takeover, MFA bypass, insecure recovery or privileged-session incident","ARL-KB-020 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='c62118a61bc97d9a0f11e7bc68f31903e90d731a06cc1e02f50a122970398fdb', updated_at='2026-08-06' WHERE id='ARL-KB-020';
UPDATE risk_knowledge_checks SET objective='Determine whether privileged administrative accounts use phishing-resistant authentication or an equivalent approved control and whether enrolment, recovery and sensitive-session paths preserve that protection.', method='Review privileged authentication policy, MFA enrolment, permitted factors, recovery, reset, session lifetime, step-up requirements and recent privileged login evidence. Verify that representative privileged accounts cannot authenticate or recover access using a weaker path that bypasses the documented protection.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-020 assessed system, version, environment and scope for Administrative accounts lack phishing-resistant protection","ARL-KB-020 control configuration or source location showing how reduce the likelihood and impact of administrative accounts lack phishing-resistant protection and make the remaining risk visible.","ARL-KB-020 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-020 policy, authorization, tool or audit events proving whether the tested administrative accounts lack phishing-resistant protection path executed","ARL-KB-020 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-020 passes only when “Administrative accounts lack phishing-resistant protection” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-020 fails when a stolen password can grant control over prompts, tools, policies, approvals or evidence, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-020 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='032edb0c8c317077076247a1cdf18ea2b5f9a2515222d1b83bddca96fa8db720', updated_at='2026-08-06' WHERE entry_id='ARL-KB-020';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of administrative accounts lack phishing-resistant protection and make the remaining risk visible.', recommended_remediation='Require strong MFA for privileged roles, protect recovery, use step-up authentication for high-impact changes and alert on risky sessions.', default_owner='Identity owner', priority='P0', implementation_principles_json='["ARL-KB-020: Require phishing-resistant authentication for privileged administrative roles where supported by the assessed platform.","ARL-KB-020: Protect enrolment, recovery and factor reset so they cannot downgrade the effective strength of privileged authentication.","ARL-KB-020: Require step-up or reauthentication for high-impact administrative changes and monitor privileged-session anomalies."]', monitoring='For ARL-KB-020, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Identity owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-020 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-020: “Administrative accounts lack phishing-resistant protection” is no longer reproducible against the exact remediated version.","ARL-KB-020: Authorised in-scope use completes successfully, remains within the documented asset scope for administrative accounts lack phishing-resistant protection, and produces no unintended side effect.","ARL-KB-020: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-020: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='e28883be9e0939ee7e7f2ba28cd893004ed5c22bed278cd8ba63b15457e2a60f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-020';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='e4c586d45e144215dc20daf19c78ea95810b4f17bd3fb20b5950aac5e5c4f10b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-020';
